package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of household membership, shared by {@link EnsureUniqueOwnerHousehold}
 * (which rejects an unshared duplicate) and {@link AssignOwnerHousehold} (which assigns the
 * shared id), so the guard and the assignment agree by construction rather than by comment.
 * Two owners are in the same household when their lastName and address match. lastName is
 * compared case-insensitively with collapsed whitespace; address is compared using the
 * shared {@link AddressNormalizer} form, so the guard and the assignment agree with the
 * address that is stored and returned.
 */
final class OwnerHousehold {

    private OwnerHousehold() {
    }

    /** Whether an owner with the given lastName and address shares a household with {@code other}. */
    static boolean isSameHousehold(String lastName, String address, Owner other) {
        return normalize(lastName).equals(normalize(other.getLastName()))
                && AddressNormalizer.normalize(address).equals(AddressNormalizer.normalize(other.getAddress()));
    }

    /** Lower-case and collapse whitespace runs to a single space for comparison. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
=== AssignOwnerHousehold ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Assigns the owner's {@code householdId} when the request opts in with
 * {@code sharesHousehold} true. Housemates — see {@link OwnerHousehold} for the membership
 * rule shared with {@link EnsureUniqueOwnerHousehold} — receive one stable shared
 * identifier: the first existing housemate's id is reused, otherwise a fresh one is minted
 * and back-filled onto every existing housemate so later joiners keep sharing it. Runs after
 * the owner is built and before it is saved; leaves {@code householdId} null when
 * {@code sharesHousehold} is not true.
 */
public class AssignOwnerHousehold {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }

        // One pass: collect the existing housemates and reuse any id they already share.
        List<Owner> housemates = new ArrayList<>();
        String householdId = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (OwnerHousehold.isSameHousehold(owner.getLastName(), owner.getAddress(), existing)) {
                housemates.add(existing);
                if (householdId == null && existing.getHouseholdId() != null) {
                    householdId = existing.getHouseholdId();
                }
            }
        }
        if (householdId == null) {
            householdId = UUID.randomUUID().toString();
        }

        // Back-fill the shared id onto any housemate that lacks it, so the whole household
        // ends up on one identifier and later joiners reuse it.
        for (Owner housemate : housemates) {
            if (housemate.getHouseholdId() == null) {
                housemate.setHouseholdId(householdId);
                ownerRepository.save(housemate);
            }
        }

        owner.setHouseholdId(householdId);
    }
}
=== OwnerTelephones ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Single definition of how an owner telephone is converted to E.164 form: strip spaces,
 * dashes and brackets; keep a leading '+' and country code when present, otherwise assume
 * country code '+61' and drop a single leading '0' from the national digits; require 8 to
 * 15 digits after the '+', and additionally require the national-number length to match the
 * country code ('+61' => 9 national digits, '+1' => 10). Both {@link NormalizeOwnerTelephone} (which normalizes the
 * incoming request) and {@link EnsureUniqueOwnerTelephone} (which normalizes stored owners
 * for comparison) call this, so the create-time rule and the dedup comparison can never
 * silently diverge.
 */
final class OwnerTelephones {

    /**
     * Required national-number length per country calling code. Iterated in order so the
     * longest matching code wins when one code is a prefix of another; the current two
     * codes ('61', '1') are not prefixes of each other, so order is immaterial here.
     */
    private static final Map<String, Integer> NATIONAL_LENGTH_BY_CODE = new LinkedHashMap<>();
    static {
        NATIONAL_LENGTH_BY_CODE.put("61", 9);
        NATIONAL_LENGTH_BY_CODE.put("1", 10);
    }

    private OwnerTelephones() {
    }

    /**
     * Converts {@code telephone} to its E.164 representation (e.g. "0412 345 678" ->
     * "+61412345678"), or returns {@code null} when it cannot form a valid E.164 number.
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        // Strip spaces, dashes and brackets; anything else must already be digits (or the
        // leading '+'), so a stray character makes the digit test below fail.
        String cleaned = telephone.replaceAll("[\\s()\\[\\]-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            // Explicit country code: keep it, just take the following digits.
            digits = cleaned.substring(1);
        } else {
            // No country code: assume '+61' and drop a single leading '0' from the national part.
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("\\d{8,15}")) {
            return null;
        }
        // Enforce the national-number length for known country codes ('+61' => 9, '+1' => 10);
        // any other code keeps only the generic 8-to-15-digit rule above.
        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_CODE.entrySet()) {
            String code = entry.getKey();
            if (digits.startsWith(code)) {
                if (digits.length() - code.length() != entry.getValue()) {
                    return null;
                }
                break;
            }
        }
        return "+" + digits;
    }
}
=== NormalizeOwnerTelephone ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the telephone on create to E.164 form: strips spaces, dashes and brackets;
 * keeps a leading '+' and country code when present, otherwise assumes country code '+61'
 * and drops a single leading '0' from the national digits; requires 8 to 15 digits after
 * the '+' and a national-number length matching the country code ('+61' => 9, '+1' => 10).
 * The E.164 string is stored back on the request so later steps build, save and
 * return it. A value that cannot form valid E.164 is rejected 400 via
 * {@link InvalidTelephoneException}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        String raw = request.getTelephone();
        String e164 = OwnerTelephones.toE164(raw);
        if (e164 == null) {
            throw new InvalidTelephoneException(raw);
        }
        request.setTelephone(e164);
    }
}

